style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* ======== Geral ======== */
  html, body {
    background: #e9edf5 !important;
    color: #2c3e50 !important;
    font-family: "Segoe UI", Tahoma, Arial, sans-serif !important;
  }

  a {
    color: #0a5aa6 !important;
    text-decoration: none !important;
  }
  a:hover {
    color: #0e73d6 !important;
    text-decoration: underline !important;
  }

  /* ======== Topbar ======== */
  header, .navbar, [class*="AppHeader"], .top-nav {
    background: linear-gradient(to bottom, #1c4a7f, #0f2c4f) !important;
    color: #eaf2ff !important;
    min-height: 44px !important;
    border-bottom: 1px solid #08203a !important;
    box-shadow: inset 0 -1px 0 rgba(255,255,255,.08), 0 1px 3px rgba(0,0,0,.35) !important;
  }
  header a, .navbar a {
    color: #eaf2ff !important;
    font-weight: 600 !important;
  }
  header a:hover, .navbar a:hover {
    text-decoration: none !important;
    filter: brightness(1.1);
  }

  /* ======== Painéis / Cards ======== */
  .card, [class*="panel"], .container-default, .content, .game-card, .store-card {
    background: #ffffff !important;
    border: 1px solid #cfd7e6 !important;
    box-shadow: 0 1px 0 rgba(255,255,255,.4), 0 1px 3px rgba(0,0,0,.15) !important;
    border-radius: 4px !important;
  }

  /* ======== Botões ======== */
  button, .btn {
    background: linear-gradient(to bottom, #2f79c7, #124a86) !important;
    border: 1px solid #0f3e6a !important;
    color: #fff !important;
    text-shadow: 0 1px 0 rgba(0,0,0,.25) !important;
    border-radius: 3px !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.25), 0 1px 2px rgba(0,0,0,.2) !important;
  }
  button:hover, .btn:hover {
    filter: brightness(1.05) !important;
  }
  button:active, .btn:active {
    transform: translateY(1px);
  }

  /* ======== Inputs ======== */
  input[type="text"], input[type="search"], [class*="search"] input {
    border: 1px solid #0b3a68 !important;
    background: #0e3f70 !important;
    color: #fff !important;
    border-radius: 2px !important;
    box-shadow: inset 0 1px 2px rgba(0,0,0,.35) !important;
  }

  /* ======== Layout ======== */
  .container, .content, #container-main {
    max-width: 980px !important;
    margin: 0 auto !important;
  }

  .sidebar, [class*="Sidebar"] {
    background: #ffffff !important;
    border: 1px solid #cfd7e6 !important;
    padding: 10px !important;
  }

  /* ======== Títulos ======== */
  h1, h2, h3, .page-title {
    font-weight: 700 !important;
    color: #1b3b63 !important;
  }
  h1 { font-size: 24px !important; }
  h2 { font-size: 20px !important; }
  h3 { font-size: 18px !important; }

  /* ======== Footer ======== */
  footer, [class*="Footer"] {
    background: #f3f6fd !important;
    color: #5a6b84 !important;
    border-top: 1px solid #cfd7e6 !important;
  }

  /* ======== Avatares / Imagens ======== */
  img, .avatar, [class*="Avatar"] img {
    border-radius: 2px !important;
  }
}
